starts=[1,8,15,22]
pattern=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
g=[[0]*30 for _ in range(30)]
for tr,r0 in enumerate(starts):
 for tc,c0 in enumerate(starts):
  for dr in range(5):
   for dc in range(5):
    g[r0+dr][c0+dc]=4 if dr in (0,4) or dc in (0,4) else pattern[tr][tc]
# connect matching non-background colors horizontally, only through zero corridors
for tr,r0 in enumerate(starts):
 for color in set(pattern[tr])-{2}:
  cols=[tc for tc,x in enumerate(pattern[tr]) if x==color]
  for left,right in zip(cols,cols[1:]):
   for tc in range(left,right):
    cgap=starts[tc]+5
    for rr in range(r0+1,r0+4):
     for cc in (cgap,cgap+1): g[rr][cc]=color
# vertical
for tc,c0 in enumerate(starts):
 vals=[pattern[tr][tc] for tr in range(4)]
 for color in set(vals)-{2}:
  rows=[tr for tr,x in enumerate(vals) if x==color]
  for top,bottom in zip(rows,rows[1:]):
   for tr in range(top,bottom):
    rgap=starts[tr]+5
    for rr in (rgap,rgap+1):
     for cc in range(c0+1,c0+4): g[rr][cc]=color
print('\n'.join(' '.join(map(str,row)) for row in g))

